// Minor-to-major money formatting. The one place this rule lives, so reporting and receipts cannot disagree.

export function formatMoneyMinor(amountMinor) {
	const sign = amountMinor < 0 ? "-" : "";
	const absolute = Math.abs(amountMinor);
	const major = Math.floor(absolute / 100);
	const minor = String(absolute % 100).padStart(2, "0");
	return `${sign}${major}.${minor}`;
}

// Parsing and validating the amount text field. Minor units throughout.

const AMOUNT_PATTERN = /^-?\d+(?:\.\d{1,2})?$/u;

export function isValidAmountText(amountText) {
	return AMOUNT_PATTERN.test(amountText);
}

export function amountMinorOf(amountText) {
	return Math.round(Number(amountText) * 100);
}

// Rejection rules, checked in the fixed order the spec requires. Each rule is a small independent check, so
// adding a rule means adding one to the list below, not another branch in a shared function.

import { CATEGORIES } from "./categories.mjs";
import { isValidAmountText, amountMinorOf } from "./amount.mjs";

function fieldCountRule(parts) {
	return parts.length !== 3 ? "expected three fields" : null;
}

function categoryRule(parts) {
	return !CATEGORIES.includes(parts[0]) ? `unknown category ${parts[0]}` : null;
}

function ownerRule(parts) {
	return parts[1] === "" ? "missing owner" : null;
}

function amountFormatRule(parts) {
	return !isValidAmountText(parts[2]) ? `bad amount ${parts[2]}` : null;
}

function refundRule(parts, options) {
	const isRefund = amountMinorOf(parts[2]) < 0 && options.allowRefunds !== true;
	return isRefund ? "refunds are not allowed" : null;
}

const RULES = [fieldCountRule, categoryRule, ownerRule, amountFormatRule, refundRule];

export function rejectionFor(parts, options) {
	for (const rule of RULES) {
		const reason = rule(parts, options);
		if (reason) return reason;
	}
	return null;
}

// Turn one raw expense line into an accepted row or a named rejection reason.

import { amountMinorOf } from "./amount.mjs";
import { rejectionFor } from "./rejectionRules.mjs";

export function splitFields(raw) {
	return raw.split(",").map((part) => part.trim());
}

export function parseLine(raw, options) {
	const parts = splitFields(raw);
	const reason = rejectionFor(parts, options);
	if (reason) return { ok: false, reason };
	const [category, who, amountText] = parts;
	return { ok: true, row: { category, who, amountMinor: amountMinorOf(amountText) } };
}

// Group accepted rows by category, in CATEGORIES order, with sorted unique owners and a rounded average.

import { CATEGORIES } from "./categories.mjs";

function addRow(byCategory, row) {
	const current = byCategory.get(row.category) ?? { category: row.category, totalMinor: 0, count: 0, owners: [] };
	current.totalMinor += row.amountMinor;
	current.count += 1;
	if (!current.owners.includes(row.who)) current.owners.push(row.who);
	byCategory.set(row.category, current);
}

export function aggregateRows(rows) {
	const byCategory = new Map();
	for (const row of rows) addRow(byCategory, row);
	return CATEGORIES.filter((category) => byCategory.has(category)).map((category) => {
		const entry = byCategory.get(category);
		const averageMinor = Math.round(entry.totalMinor / entry.count);
		return { ...entry, owners: [...entry.owners].sort(), averageMinor };
	});
}

// Render aggregates as the fixed-width report table, ending with a TOTAL row over accepted rows.

import { CATEGORIES } from "./categories.mjs";
import { formatMoneyMinor } from "./money.mjs";

function padRow(label, amountMinor, count, width) {
	const amount = formatMoneyMinor(amountMinor).padStart(10, " ");
	return `${label.padEnd(width, " ")}  ${amount}  ${String(count).padStart(3, " ")}`;
}

export function renderTable(aggregates, totalMinor, acceptedCount) {
	const width = Math.max(...CATEGORIES.map((category) => category.length));
	const lines = aggregates.map((entry) => padRow(entry.category, entry.totalMinor, entry.count, width));
	lines.push(padRow("TOTAL", totalMinor, acceptedCount, width));
	return lines.join("\n");
}

// Expense reporting pipeline: parse each line, aggregate accepted rows, render the table and the CSV export.

import { parseLine } from "./parsing.mjs";
import { aggregateRows } from "./aggregate.mjs";
import { renderTable } from "./table.mjs";
import { formatMoneyMinor } from "./money.mjs";

function isSkippable(raw) {
	return raw === "" || raw.startsWith("#");
}

export function buildReport(text, options) {
	const opts = options ?? {};
	const lines = String(text ?? "").split("\n");
	const rows = [];
	const rejected = [];
	for (let index = 0; index < lines.length; index += 1) {
		const raw = lines[index].trim();
		if (isSkippable(raw)) continue;
		const parsed = parseLine(raw, opts);
		if (!parsed.ok) rejected.push({ line: index + 1, reason: parsed.reason });
		else rows.push(parsed.row);
	}
	const aggregates = aggregateRows(rows);
	const totalMinor = aggregates.reduce((sum, entry) => sum + entry.totalMinor, 0);
	return { aggregates, rejected, table: renderTable(aggregates, totalMinor, rows.length), totalMinor };
}

export function exportReportCsv(report) {
	const out = ["category,total,count,owners"];
	for (const entry of report.aggregates) {
		const major = formatMoneyMinor(entry.totalMinor);
		out.push(`${entry.category},${major},${entry.count},${entry.owners.join(" ")}`);
	}
	return out.join("\n");
}

// Receipt rendering. Shares the money formatter with reporting, so the two cannot drift apart.

import { formatMoneyMinor } from "./money.mjs";

export function renderReceipt(row) {
	if (!row || typeof row.category !== "string") {
		throw new TypeError("a receipt needs a category");
	}
	const major = formatMoneyMinor(row.amountMinor);
	const padded = row.category.padEnd(8, " ");
	const owner = String(row.who ?? "").padEnd(12, " ");
	const amount = major.padStart(10, " ");
	return `${padded}${owner}${amount}`;
}

export { CATEGORIES } from "./categories.mjs";
export { buildReport, exportReportCsv } from "./reporting.mjs";
export { renderReceipt } from "./receipts.mjs";
